function values = simuverity_xfluid04_public_nominal_inputs(benchmarkTaskId, publicNames)
%simuverity_xfluid04_public_nominal_inputs Public-only nominal values.
benchmarkTaskId = string(benchmarkTaskId);
assert(benchmarkTaskId == "F90-XFLUID-04", ...
    "SimuVerity:CandidateClosure:Xfluid04Task", ...
    "This task-local provider only serves F90-XFLUID-04.");
expected = sort(["lift_target_mm"; "motion_start_s"; ...
    "ramp_duration_s"; "target_hold_s"; "supply_pressure_bar"; ...
    "supply_pressure_step_fraction"; "pressure_step_offset_s"]);
actual = sort(unique(string(publicNames(:)), "stable"));
actual(actual == "") = [];
assert(isequal(actual, expected), ...
    "SimuVerity:CandidateClosure:Xfluid04Names", ...
    "Public nominal input names do not match the task contract.");
values = struct( ...
    "lift_target_mm", 120.0, ...
    "motion_start_s", 1.5, ...
    "ramp_duration_s", 4.0, ...
    "target_hold_s", 5.0, ...
    "supply_pressure_bar", 200.0, ...
    "supply_pressure_step_fraction", -0.08, ...
    "pressure_step_offset_s", 2.0);
end
